import { type BlockInstance } from '@wordpress/blocks';
import { type ModuleLibrary } from '@divi/types';
/**
 * Interface for module instance.
 *
 * This interface extending BlockInstance interface to have the proper innerBlocks property
 * type declaration when doing serialization.
 *
 * @since ??
 */
export interface ModuleInstance<TAttrs> extends BlockInstance<TAttrs> {
    innerBlocks: ModuleLibrary.Module.Component.Instance<TAttrs>[];
}
/**
 * Component props of module that is rendered on visual builder' app.
 *
 * @since ??
 */
export type ModuleEditProps<TAttrs, TParentAttrs = unknown, TChildAttrs = unknown> = ModuleLibrary.Module.Component.EditProps<TAttrs, TParentAttrs, TChildAttrs>;
